package com.bank.iac;

// One line of a terraform plan.
public class ProposedChange {
    private final String address;
    private final ChangeAction action;
    private final boolean stateful;        // true = holds data we cannot lose (RDS, EBS)
    private final String reason;           // e.g. "instance_class forces replacement"

    public ProposedChange(String address, ChangeAction action, boolean stateful, String reason) {
        this.address = address;
        this.action = action;
        this.stateful = stateful;
        this.reason = reason;
    }

    public String getAddress() { return address; }
    public ChangeAction getAction() { return action; }
    public boolean isStateful() { return stateful; }
    public String getReason() { return reason; }
}
