package com.bank.iac;

import java.util.List;
import java.util.logging.Logger;

// Classifies a plan and refuses to approve if a stateful resource would be replaced.
public class PlanAnalyzer {
    private static final Logger log = Logger.getLogger(PlanAnalyzer.class.getName());

    // Returns true only if the plan is safe to apply to production.
    public boolean isSafeToApply(List<ProposedChange> plan) {
        boolean safe = true;
        for (ProposedChange c : plan) {
            switch (c.getAction()) {
                case CREATE:
                    log.info(() -> "  + " + c.getAddress() + " — create (safe)");
                    break;
                case UPDATE:
                    log.info(() -> "  ~ " + c.getAddress() + " — update in place (safe)");
                    break;
                case DESTROY:
                    log.warning(() -> "  - " + c.getAddress() + " — destroy (review why)");
                    break;
                case REPLACE:
                    if (c.isStateful()) {
                        // THE red alert: a stateful resource being destroyed-and-recreated.
                        log.severe(() -> "  -/+ " + c.getAddress()
                                + " — REPLACE of STATEFUL resource! " + c.getReason()
                                + " => DATA LOSS / DOWNTIME. BLOCK.");
                        safe = false;
                    } else {
                        log.warning(() -> "  -/+ " + c.getAddress()
                                + " — replace of stateless resource (" + c.getReason()
                                + ") — brief gap, usually acceptable");
                    }
                    break;
            }
        }
        if (safe) {
            log.info("Verdict: plan is SAFE to apply.");
        } else {
            log.severe("Verdict: plan is NOT safe — a stateful resource would be replaced. "
                     + "Use create_before_destroy / state mv / blue-green instead.");
        }
        return safe;
    }
}
