package com.bank.iac;

import java.util.List;
import java.util.logging.*;

// Runnable demo: a module upgrade whose plan hides a dangerous RDS replacement.
public class ModuleUpgradeDemo {
    private static final Logger log = Logger.getLogger(ModuleUpgradeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — upgrading stale 'rds' module v3.2.0 -> v4.0.0");
        log.info("Reading plan from NON-PROD workspace before touching prod ledger...");

        // The plan Terraform produced after the module + provider bump.
        List<ProposedChange> plan = List.of(
            new ProposedChange("module.ledger_rds.aws_db_instance.this",
                ChangeAction.REPLACE, true,
                "instance_class attribute recomputed by new provider forces replacement"),
            new ProposedChange("module.ledger_rds.aws_security_group_rule.ingress",
                ChangeAction.REPLACE, false,
                "description change forces rule replacement"),
            new ProposedChange("module.ledger_rds.aws_db_parameter_group.this",
                ChangeAction.UPDATE, false,
                "new parameter added in place")
        );

        PlanAnalyzer analyzer = new PlanAnalyzer();
        boolean safe = analyzer.isSafeToApply(plan);

        if (!safe) {
            log.severe("Aborting apply. Ledger database SAV2001/CUR3001 transactions protected.");
            log.info("Next: add lifecycle create_before_destroy OR migrate blue-green, re-plan.");
        }
    }
}
